def ic(k): return f'<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{I[k]}</svg>'
def dot(k,cls=''): return f'<div class="dot {cls}">{ic(k)}</div>'
def q(k,label,cls='',n=''): return f'<div class="q {cls}">{f"<b class=n>{n}</b>" if n else ""}{ic(k) if k else ""}<span>{label}</span></div>'
def pad(color,qs,cls=''): return f'<div class="pad {color} {cls}"><i class="v"></i><i class="h"></i>{"".join(qs)}</div>'
def info(lines,tabs=None,cls=''):
    t=''.join(f'<em class="{"on" if i==0 else ""}">{x}</em>' for i,x in enumerate(tabs)) if tabs else ''
    return f'<div class="pad blue info {cls}">{f"<div class=tabs>{t}</div>" if t else ""}{"".join(f"<p>{l}</p>" for l in lines)}</div>'
def top(pill): return f'<div class="top">{dot("home","brown")}{dot("back")}{dot("follow")}<div class="pill">{pill}</div>{dot("stop")}{dot("x")}{dot("exit","red")}</div>'
ST='<b>Gathering: food</b> · with 4 others'
L=['<b>Gathering: food</b> · 5 on it','now: berries → then: build house','<small>tap: Orders · History · Stats</small>']
H=['<b>History</b>','0:00–1:12 · food 84','1:12–1:40 · building house','1:40–now · food 31']
