V.append(('3 · Info card with tabs',top('Select the rest · 4'),pad('brown',[q('add','Add task'),q('build','Build'),q('gar','Garrison'),q('grp','New group')]),info(['<b>Gathering: food</b> · 5 on it','now: berries','then: build house'],tabs=['Orders','History','Stats']),pad('red',[q('att','Normal','lit'),q('load','Drop','lit'),q('stop','Stop'),q('x','Cancel')])))
V.append(('4 · Info card on the left, tasks centre',top('Gathering: food · 5'),info(H,cls='brownbg'),pad('blue',[q('add','Add task'),q('build','Build'),q('gar','Garrison'),q('grp','New group')]),pad('red',[q('att','Normal','lit'),q('load','Drop','lit'),q('hist','History'),q('stat','Stats')])))
V.append(('5 · Wide info card, one pad',top('<b>Villager</b>'),f'<div class="pad blue info wide"><p><b>Gathering: food</b> · with 4 others · <u>select all 5</u></p><p>now: berries → then: build house</p><p class="dim">0:00–1:12 food 84 · 1:12–1:40 house · 1:40–now food 31</p></div>',pad('red',[q('add','Add task'),q('build','Build'),q('att','Normal','lit'),q('load','Drop','lit')])))
V.append(('6 · Settings page (like the war pages)',top('Gathering: food · 5'),pad('brown',[q('add','Add task'),q('build','Build'),q('gar','Garrison'),q('grp','New group')]),info(L),pad('red',[q('att','Normal','lit'),q('att','Focus'),q('att','Mobile'),q('load','Load: Drop')],'set')))
CSS=open('style.css').read()
html=f'<!DOCTYPE html><html><head><meta charset=utf-8><link rel=stylesheet href=fonts.css><style>{CSS}</style></head><body>'+''.join(f'<div class="ph"><div class="cap">{t}</div><div class="map"></div><div class="ctl">{tp}<div class="pads">{a}{b}{c}</div></div></div>' if len(x)==5 else f'<div class="ph"><div class="cap">{x[0]}</div><div class="map"></div><div class="ctl">{x[1]}<div class="pads two">{x[2]}{x[3]}</div></div></div>' for x in V for t,tp,a,b,c in [x if len(x)==5 else (None,)*5])+'</body></html>'
open('opts.html','w').write(html)
